 }).join('')}</div>${s.powers.star?`<section class="card"><h3>天星覇権 Lv.5</h3><p>${POWERS.find(x=>x.id==='star').effect}</p>${button(s.equipped.includes('star')?'装備解除':'装備する','equipPower','star','primary')}</section>`:''}`;}
