/* Summon presentation: saved results only, no timers or additional rolls. */
.summon-sanctuary{position:relative;height:210px;border-radius:16px;overflow:hidden;border:1px solid #9d7dc955;background:#100f21}
.summon-sanctuary img{width:100%;height:100%;object-fit:cover;object-position:center}
.summon-sanctuary span{position:absolute;inset:auto 0 0;padding:32px 16px 16px;background:linear-gradient(transparent,#111120);font-weight:700;letter-spacing:.08em}
.summon-wallet{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:14px;color:#d9ccea}
.summon-wallet strong{color:#f6d789}.summon-collection-progress{width:100%;height:8px;accent-color:#cfabf2}
.summon-dialog{width:min(640px,calc(100vw - 24px));max-height:calc(100dvh - 32px);overflow:auto;box-sizing:border-box}
.summon-dialog h2{font-size:clamp(18px,4.6vw,24px)}
.summon-opening{display:grid;place-items:center;height:80px;color:#e8c97d;background:radial-gradient(ellipse,#ab71dc50,transparent 65%);animation:summon-star .65s ease-out both}
.summon-progress{text-align:center;color:#e7d4ff;font-weight:700}
.summon-results{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:16px 0}
.summon-result{min-width:0;min-height:150px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:12px 8px;border:1px solid #9d7dc966;border-radius:12px;background:linear-gradient(150deg,#312342,#101323);text-align:center;animation:summon-card .3s ease-out both}
.summon-result strong{font-size:14px;overflow-wrap:anywhere}.summon-result small{font-size:12px;line-height:1.6;color:#ddd3e7}
.summon-result.discovery{border-color:#e7c77d;box-shadow:inset 0 0 24px #d5ae4622}.summon-label{font-size:11px;letter-spacing:.06em;color:#e9c777}
.summon-seal{color:#dab6ff}.summon-result.sealed{background:radial-gradient(circle,#45285e,#151626);color:#b28bcf;font-size:36px}
.summon-dialog>.row{position:sticky;bottom:-1px;background:#141525;padding:12px 0;margin-bottom:0;display:flex;flex-wrap:wrap;gap:8px}
.summon-dialog button{min-height:44px;flex:1 1 100px}.summon-dialog .small{line-height:1.7}
@keyframes summon-star{from{opacity:0;transform:scale(.6) rotate(-45deg)}to{opacity:1;transform:scale(1) rotate(0)}}
@keyframes summon-card{from{opacity:.2;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
@media(min-width:600px){.summon-results{grid-template-columns:repeat(5,minmax(0,1fr))}.summon-result:only-child{grid-column:2/5}}
@media(prefers-reduced-motion:reduce){.summon-opening,.summon-result{animation:none}}

.rarity-R{--summon-color:#8edbff}.rarity-SR{--summon-color:#d6a0ff}.rarity-SSR{--summon-color:#ffe09a}
.summon-rates{font-size:14px;line-height:1.8}.summon-rates summary{min-height:44px;cursor:pointer;padding:10px 0}.summon-rates b{color:var(--summon-color)}.summon-rates ul{padding-left:20px}
.summon-result .summon-label,.summon-result .summon-seal{color:var(--summon-color)}
#cinema.summon-cinema{background:radial-gradient(ellipse at center,#271b39,#080a16 70%);overflow:hidden;isolation:isolate}
#cinema.summon-cinema .cinema-copy{z-index:2;text-align:center;color:var(--summon-color);animation:none;padding:16px}
#cinema.summon-cinema h2{font-size:clamp(64px,18vw,150px);letter-spacing:.12em;color:var(--summon-color);text-shadow:0 0 38px var(--summon-color);animation:summon-tier .9s ease-out both}
#cinema.summon-cinema p{color:#f1e9ff;font-size:clamp(16px,4vw,24px)}
#cinema.summon-cinema #skipCinema{position:fixed;z-index:4;top:calc(14px + env(safe-area-inset-top));right:calc(14px + env(safe-area-inset-right));bottom:auto;left:auto;min-height:48px;min-width:110px;font-family:var(--serif);font-size:16px;letter-spacing:.1em;border:1px solid #b99b6a99;background:#15111fe8;color:#efdab4;border-radius:8px;box-shadow:0 3px 16px #0008}
.summon-field{position:absolute;inset:0;display:grid;place-items:center;pointer-events:none;color:var(--summon-color)}
.summon-crest{position:absolute!important;width:min(90vw,600px)!important;height:min(90vw,600px)!important;object-fit:contain!important;opacity:.22!important;animation:summon-emerge 1.3s ease-out both!important}
.summon-ring{position:absolute;width:min(78vw,540px);aspect-ratio:1;border:2px solid currentColor;border-radius:50%;box-shadow:0 0 30px currentColor,inset 0 0 20px currentColor;opacity:.5;animation:summon-orbit 1.6s ease-out both}
.summon-ring.outer{width:min(98vw,700px);border-style:dashed;animation-duration:2.3s;opacity:.3}
.summon-ray{position:absolute;width:2px;height:25vh;background:linear-gradient(transparent,currentColor,transparent);transform:rotate(var(--angle)) translateY(-32vh);animation:summon-ray 1.2s ease-out var(--delay) both}
#cinema.summon-cinema.rarity-R .outer{display:none}#cinema.summon-cinema.rarity-SR .summon-ring{border-radius:22%}#cinema.summon-cinema.rarity-SSR{background:radial-gradient(ellipse,#66522b,#211629 42%,#080a16 80%)}
@keyframes summon-tier{from{opacity:0;transform:scale(.55);filter:blur(8px)}to{opacity:1;transform:scale(1);filter:blur(0)}}
@keyframes summon-emerge{from{transform:scale(.7) rotate(-15deg)}to{transform:scale(1) rotate(0)}}
@keyframes summon-orbit{from{transform:scale(.5) rotate(-90deg)}to{transform:scale(1) rotate(30deg)}}
@keyframes summon-ray{from{opacity:0;translate:0 20px}to{opacity:.6;translate:0 0}}
@media(prefers-reduced-motion:reduce){#cinema.summon-cinema *,#cinema.summon-cinema .summon-crest{animation:none!important;filter:none!important}}

