.upgrade-power-card.state-equipped{border-color:#6dcaae}
.upgrade-power-card.state-max{border-color:#c79a49}
.upgrade-power-card.state-locked,.upgrade-power-card.state-unowned{border-color:#4a4d60}
.upgrade-power-main{display:grid;grid-template-columns:minmax(0,42%) minmax(0,1fr);align-items:start;gap:10px;padding-right:34px;min-width:0}
.upgrade-power-card .upgrade-power-art{width:100%;height:auto;aspect-ratio:1;object-fit:cover;border-radius:6px;border:1px solid #5b497d}
