.upgrade-power-card h3{font-size:clamp(15px,2vw,22px);line-height:1.3;overflow-wrap:anywhere}
.upgrade-power-level{font-size:13px;color:#e1d8f6}
.upgrade-power-meter{height:5px;width:100%;background:#353650;border-radius:99px;overflow:hidden}
.upgrade-power-meter span{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#ad78d5,#f2c782)}
.upgrade-power-status{display:inline-flex;align-items:center;justify-content:center;border:1px solid #55576b;background:#232437;color:#c8c8d2;font-size:11px;font-weight:700;border-radius:6px;padding:2px 7px;white-space:nowrap}
.state-equipped .upgrade-power-status{background:#07392d;color:#79f8ce;border-color:#159975}
.state-ready .upgrade-power-status{background:#082c49;color:#86cdff;border-color:#218dd5}
.state-max .upgrade-power-status{background:#47310c;color:#ffe1a0;border-color:#b77e21}
.state-locked .upgrade-power-status,.state-unowned .upgrade-power-status{background:#22222b;color:#c2c0c9;border-color:#68616e}
.upgrade-power-card .upgrade-power-effect{min-height:0;margin:0;font-size:12px;line-height:1.48;color:#dfd8e8;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.upgrade-power-card .upgrade-power-cost{min-height:0;margin-top:auto;padding-top:5px;font-size:12px;white-space:normal;color:#e7c5ff}
.upgrade-power-card .upgrade-power-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:0;padding:0}
.upgrade-power-card .upgrade-power-actions:has(>button:only-child){grid-template-columns:1fr}
.upgrade-power-actions button{min-height:44px;padding:6px 3px;font-size:12px;white-space:nowrap}
.upgrade-power-detail{top:11px;right:11px;min-height:44px;min-width:44px}
.upgrade-detail-modal{display:grid;gap:12px;padding-top:10px}
.upgrade-detail-image{width:100%;max-height:180px;object-fit:cover;border-radius:8px;border:1px solid #705291}
.upgrade-detail-section,.upgrade-detail-facts>div{background:#181729;border:1px solid #4d405f;border-radius:8px;padding:11px 13px}
.upgrade-detail-section small,.upgrade-detail-facts small{color:#bdb0cb;font-size:12px;display:block}
.upgrade-detail-section p{margin:4px 0 0;line-height:1.65;font-size:14px}
.upgrade-detail-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
.upgrade-detail-facts>div:last-child:nth-child(odd){grid-column:1/-1}
.upgrade-detail-facts strong{display:block;font-size:14px;margin-top:3px;line-height:1.5;color:#f7e6ff}
@media(max-width:700px){
