.badge-locked,.badge-unowned{color:#ddd8e4;background:#2c2936;border-color:#776c88}
.upgrade-power-card.state-insufficient{border-color:#9c794a}
.upgrade-power-card.equipped{box-shadow:inset 3px 0 #69c6a8}
.upgrade-power-card .upgrade-power-cost{font-size:13px;padding:0;line-height:1.5}
.upgrade-power-card .upgrade-power-actions{gap:6px}
.upgrade-power-card .upgrade-power-actions button{font-size:13px;min-height:44px;padding:7px 2px;white-space:normal}
