.upgrade-detail-section.next-effect{border-color:#68799e;background:#171e32}
.detail-growth{margin-top:10px;font-size:14px;line-height:1.6;color:#d6cbe5}
.detail-growth strong{color:#e5ccff;white-space:nowrap}
.power-detail-materials{display:grid;gap:0;margin:0;border:1px solid #5d506e;border-radius:9px;overflow:hidden}
