.sortie-finale{flex-direction:column;background:radial-gradient(ellipse,#22102f,#06050c 75%)}.sortie-finale .sortie-frame{width:min(100vw,145dvh,1200px);box-shadow:0 0 60px #68315d40}.sortie-finale .sortie-sheen{display:none}.sortie-finale-title{font:700 clamp(16px,4.8vw,28px)/1.4 var(--serif);color:#eddaef;letter-spacing:.1em;text-align:center;margin:24px 14px 0;text-shadow:0 0 18px #aa70db}
