.final-commands .command-block-label{display:block;font-size:10px;line-height:1.3;color:#efd39e}
.final-commands .skill:disabled{opacity:.68;border-color:#65526b;cursor:not-allowed}
.guard-focus-description{padding:12px;border:1px solid #63513d;border-radius:10px;background:#28202b;margin:15px 0}.guard-focus-description p{font-size:13px;line-height:1.8}
