 #app.combat-live .battle-controls.final-commands .glyph,#app.combat-live .battle-controls.final-commands .has-art,#app.combat-live .battle-controls.final-commands .skill-art{width:24px;height:24px}
 #app.combat-live .battle-controls.final-commands .glyph svg{width:22px;height:22px}
