 #app.combat-live .battle-controls.final-commands .command-block-label{font-size:9px;line-height:10px;margin-top:1px;overflow-wrap:anywhere}
 #app.combat-live .enemy-deadline{font-size:9px;line-height:11px;margin-left:4px;padding:0 3px}
}
/* audit19: first-slot authority reveal and distinct impact shapes; layout-neutral. */
.battle-stage .vfx-authority-veil{inset:0;z-index:16;background:linear-gradient(90deg,#090711ee,#100a14c9,#090711dd)}
.battle-stage .vfx-authority-cutin{left:0;top:50%;width:100%;height:auto;aspect-ratio:1672/941;max-height:100%;z-index:17;overflow:hidden;border-block:1px solid var(--authority-color);background:#09070e;box-shadow:0 0 22px #0008}
.battle-stage .vfx-authority-cutin img{object-fit:contain!important}
.battle-stage .vfx-authority-title{position:absolute;left:4%;bottom:14%;font:700 clamp(22px,6vw,42px)/1.1 var(--serif);letter-spacing:.12em;color:#fff7ec;text-shadow:0 2px 6px #000,0 0 10px #000;padding:9px 12px;background:linear-gradient(90deg,#090711e6,#09071188,transparent);border-left:2px solid var(--authority-color)}
.vfx-authority-title small{display:block;color:var(--authority-color);font:600 clamp(9px,2.1vw,12px)/1.8 Georgia,serif;letter-spacing:.24em}
.vfx-authority-caption{position:absolute;left:calc(4% + 14px);bottom:5%;color:#fff0e8;font:normal clamp(10px,2.6vw,14px)/1.3 var(--serif);text-shadow:0 2px 5px #000,0 0 6px #000}
.battle-stage .vfx-authority-focus,.battle-stage .vfx-authority-impact{left:50%;top:46%;width:76%;aspect-ratio:1;border:2px solid var(--authority-color);border-radius:50%;box-shadow:inset 0 0 22px var(--authority-color),0 0 14px var(--authority-color);z-index:10}
.battle-stage .vfx-authority-piece{left:50%;top:46%;width:75%;height:3px;background:linear-gradient(90deg,transparent,var(--authority-color),#fff2df,transparent);transform-origin:center;z-index:10}
.battle-stage .vfx-authority-impact.vfx-authority-feathers{border:0;border-radius:0;background:linear-gradient(24deg,transparent 44%,#fff1df 49%,var(--authority-color) 51%,transparent 56%);box-shadow:none}
.battle-stage .vfx-authority-piece.vfx-authority-feathers{left:calc(22% + var(--piece)*9%);height:70%;width:13%;background:linear-gradient(160deg,#110b17 20%,var(--authority-color) 65%,#ffe2d4);clip-path:polygon(10% 0,100% 25%,58% 100%,0 65%)}
.battle-stage .vfx-authority-impact.vfx-authority-judgment{border-radius:0;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
.battle-stage .vfx-authority-piece.vfx-authority-judgment{left:calc(25% + var(--piece)*25%);top:40%;width:6%;height:90%;background:linear-gradient(0deg,transparent,var(--authority-color),#fff9e4,transparent);box-shadow:0 0 9px var(--authority-color)}
.battle-stage .vfx-authority-impact.vfx-authority-vortex{background:radial-gradient(ellipse,#04020df5 22%,#6c368277 48%,transparent 70%);border-style:dashed}
.battle-stage .vfx-authority-piece.vfx-authority-vortex{width:calc(48% + var(--piece)*22%);height:auto;aspect-ratio:1;border:2px solid var(--authority-color);border-left-color:transparent;border-radius:50%;background:transparent}
.battle-stage .vfx-authority-impact.vfx-authority-rupture{background:radial-gradient(circle,#fff5e7 0%,#f6656d88 16%,transparent 62%);border-color:#ff7e89}
.battle-stage .vfx-authority-piece.vfx-authority-rupture{width:90%;height:5px}
.battle-stage .vfx-authority-impact.vfx-authority-crown{border-radius:0;background:linear-gradient(0deg,#e7a35b44,transparent);clip-path:polygon(0 25%,25% 46%,50% 0,75% 46%,100% 25%,90% 90%,10% 90%)}
.battle-stage .vfx-authority-piece.vfx-authority-crown{left:calc(16% + var(--piece)*17%);top:36%;height:55%;width:3px;background:linear-gradient(0deg,transparent,var(--authority-color),#fff9e4)}
