.sortie-overlay:not(.sortie-finale){isolation:isolate;background:#07040c}
.sortie-atmosphere{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:-1;background:radial-gradient(ellipse at 50% 23%,#551035a8,transparent 58%),radial-gradient(ellipse at 50% 80%,#3e165c99,transparent 60%)}
