.sortie-particle:nth-child(3n){width:2px;height:2px;background:#c58aff;box-shadow:0 0 9px #9334f9}
.sortie-feather{position:absolute;left:var(--x);top:var(--y);width:14px;height:65px;border-radius:90% 0 80% 10%;background:linear-gradient(100deg,#040308 30%,#231029 64%,#7a284b 69%,#090610 76%);box-shadow:1px 0 2px #b32c6755;transform:rotate(var(--r));animation:sortie-feather-flight var(--sortie-duration) ease-out both}
