@keyframes sortie-ray-sweep{0%{translate:-60% 100px;opacity:0}25%{opacity:.85}100%{translate:35% -130px;opacity:0}}
@keyframes sortie-ember-rise{0%{translate:-20px 55px;opacity:0}25%{opacity:1}100%{translate:35px -90px;opacity:0}}
@keyframes sortie-feather-flight{0%{translate:-35px 75px;rotate:-20deg;opacity:0}20%{opacity:.95}100%{translate:65px -75px;rotate:40deg;opacity:0}}
