.mirror-gate-copy{position:relative;padding:40px 32px;max-width:470px}.mirror-eyebrow{font-size:10px;font-weight:700;letter-spacing:.2em;color:#edb4b8}.mirror-gate h2{font-family:serif;font-size:clamp(30px,4vw,48px);letter-spacing:.06em;margin:22px 0 16px;color:#fff0e8;text-shadow:0 4px 18px #000}.mirror-quote{line-height:1.9;color:#e8ccd6;font-family:serif;font-size:17px}.mirror-gate-meta{display:flex;gap:8px;margin:24px 0 12px;font-size:11px;color:#e5b8c3}.mirror-gate-meta span{border:1px solid #a85a6d66;padding:5px 8px;border-radius:4px;background:#1d0e1ba0}.mirror-enter{min-height:52px;width:100%;max-width:320px;background:linear-gradient(110deg,#672239,#b64a5d,#722138);border:1px solid #eb9b99;color:#fff3e5;box-shadow:0 0 28px #bc304b33;font-family:serif;letter-spacing:.12em;font-size:18px}.mirror-gate-copy>small{display:block;color:#bca2af;font-size:11px;margin-top:10px}
.mirror-stage{--mirror-accent:#ff617e;background:#100b16 var(--mirror-arena) center/cover!important;border-color:#703c58!important}.mirror-stage .fighter{background:linear-gradient(115deg,#100d1ac9,#240b1c80)!important;border-color:#654157!important}.mirror-stage .fighter-enemy .portrait-frame{background:radial-gradient(ellipse,#bd254126,transparent 70%)!important}.mirror-stage .fighter-enemy .sprite{width:100%!important;height:100%!important;object-fit:contain!important;object-position:center 45%!important;filter:drop-shadow(0 0 10px #b32952aa)}.mirror-stage .mirror-state{color:#ffd0da!important;font-size:10px!important;line-height:1.35!important;max-width:100%;white-space:normal}.mirror-stage.mirror-awake{--mirror-accent:#f5c475;border-color:#c19154!important}.mirror-stage.mirror-awake .fighter-enemy{border-color:#b48b53!important;background:linear-gradient(115deg,#211711d9,#50371a85)!important}.mirror-stage.mirror-awake .fighter-enemy .sprite{filter:drop-shadow(0 0 10px #d29b41a0)}.mirror-stage .health:not(.player) .hp-current{background:linear-gradient(90deg,#b92b56,var(--mirror-accent))!important}
